from pathlib import Path
import json,statistics,math
p=Path('training/diagnosis-v7');r=json.loads((p/'results.json').read_text());assert 'games' in r
cv=r['crossValidation'];start=statistics.mean(v[0]['outOfFoldRMSE'] for v in cv.values());train=statistics.mean(v[-1]['trainRMSE'] for v in cv.values());test=statistics.mean(v[-1]['outOfFoldRMSE'] for v in cv.values());c=r['comparisons']['exact4-exact3'];lo,hi=c['paired95CI'];ctx=r['contextAliasing'];inter=r['interference']
lines=['# V7 强化学习诊断结果','', '本轮定位上一轮没有提高1536成功率的原因，未训练或上线新的游戏策略。网页默认AI仍为V4。所有实战使用固定的V7起点模型，而不是V7最终候选。','', '## 1. 搜索老师是否真的更强','', '在同一组512个新开局上，分别运行到首次1536或真实死亡。完整搜索要求每一步都完成指定深度，没有浏览器时间限制。主比较在观察胜负结果前固定为“完整4层减完整3层”。','', '|策略|合出1536|成功率|平均每局CPU秒|','|---|---:|---:|---:|']
for mode,label in [('current3','原限额3层'),('exact3','完整3层'),('exact4','完整4层')]:
 g=r['games'][mode];lines.append(f"|{label}|{g['wins']}/{g['n']}|{g['rate']:.2%}|{g['meanCPUSeconds']:.3f}|")
lines += ['',f"完整4层相对完整3层：{c['difference']*100:+.2f}个百分点，配对95%区间[{lo*100:+.2f}, {hi*100:+.2f}]个百分点；仅4层成功{c['onlyA']}局，仅3层成功{c['onlyB']}局，精确McNemar p={c['mcnemarExactP']:.4f}。",'', '512局属于诊断规模，不能把不显著解释成两者等效，也不能排除约1个百分点的小变化。完整4层的计算成本不代表手机网页可接受的延迟。本轮没有测试6144。','', '本次预先指定的主比较支持完整4层优于完整3层。计算成本约为完整3层的57.6倍；这只是冻结同一价值模型后改变搜索深度的结果，不是新训练学生模型的成绩。','', '旧教师在256个困难局面中只有44个搜完4层，只有11个改变了原策略的行动。强制搜完4层后，有63个改变行动。行动相同不等于数值标签完全相同；这些数字只能说明旧教师增加的行动纠错有限。','', '## 2. 学不进去，还是不能泛化','', '用原来的951条教师标签做纯监督诊断。按来源对局分组，避免同局相邻局面进入两边；D4对称等价棋盘也不得跨训练/测试集合。原始诊断为80局训练、20局测试；随后加入5折交叉验证作为敏感性检查。三个种子只改变监督学习样本顺序，不是三个独立强化学习训练。','', '|5折汇总，三个顺序种子均值|训练RMSE|跨对局测试RMSE|','|---|---:|---:|',f'|训练前|{start:.1f}|{start:.1f}|',f'|教师样本训练100轮后|{train:.1f}|{test:.1f}|','',f'训练误差下降{(1-train/start):.1%}，跨对局误差变化{(test/start-1):+.1%}。模型可以拟合训练标签，但在这组数据上泛化很弱。10轮的测试误差仅有约0.5%的下降，继续训练没有扩大收益。','', 'V7原候选对全部教师标签的RMSE由起点5897.4降到5115.2，下降约13.3%。这是训练内拟合审计，不能称为独立测试集表现；说明它确实吸收了部分教师信号。','', '教师纠错标签来自100局失败对局，不能据此说全部RL训练只有100局：普通TD训练实际有数千万次更新。现有证据指向教师数据/表示的泛化瓶颈，但尚不能唯一分开数据多样性、模型表示和标签噪声各自的作用。','', '## 3. 一个明确的输入信息瓶颈','', '老师的Q值标签依赖棋盘、预览牌和公开剩余牌数；蒸馏后的价值表只输入棋盘。游戏搜索会使用预览牌，但价值表拟合时没有这些条件。','',f"在{ctx['sourceBoards']}个棋盘的{ctx['afterstates']}个固定行动后棋盘上，只改变从同一抽牌前牌袋可出现的普通预览牌，并同步调整剩余牌数，完整3层老师的目标值范围中位数为{ctx['medianTargetRange']:.1f}分。学生对相同棋盘只能输出一个数。",'', f"这些反事实条件下的加权方差给出约{ctx['contextOnlyIrreducibleRMSE']:.1f}分的不可约RMSE下界。它只适用于本测试构造的条件数据，不能作为原951条标签的误差下界，更不能换算成1536成功率。",'', '这证明存在信息压缩损失，不等于证明它解释了上一轮全部失败。下一步应比较：给价值模型加入相关公开上下文，或把教师标签按学生可见信息正确求平均。','', '## 4. 普通更新是否冲淡教师信号','', '从充分拟合过教师训练集的模型出发，用固定的100局新开局产生约5万条普通TD标签；所有组回放同样的标签、同样的顺序5遍。只改变教师更新占普通TD更新的次数比例。TD学习率.003，教师学习率.001。三个顺序种子。','', '|教师更新比例|回放前教师训练RMSE|回放后教师训练RMSE|回放后留出对局RMSE|','|---|---:|---:|---:|']
for ratio in ['0','0.0021','0.02','0.1']:
 x=inter[ratio];lines.append(f"|{float(ratio):.2%}|{x['initialTrainRMSE']:.1f}|{x['finalTrainRMSE']:.1f}|{x['finalHeldoutRMSE']:.1f}|")
lines += ['', '普通更新确实会部分冲淡已拟合的教师信号；接近旧训练的0.21%更新比例抵消作用很小。加到10%能保留更多训练内信号，但几乎没有改善留出误差。这个受控回放不是完整在线RL，也没有测量各比例的游戏成功率，不能直接推荐10%为最优配置。','', '## 结论与尚未验证的因素','', '目前有直接证据的瓶颈是：教师知识跨对局泛化弱、条件标签与棋盘输入之间有信息损失，以及普通TD对教师信号存在干扰。独立实战支持完整4层老师更强，而旧教师多数局面未完成4层。尚不能量化各因素分别解释了上一轮多少成功率损失。','', '得分目标与1536概率目标的差异、训练2层与部署3层的分布差异、以及应提前多少步采样失败前局面，仍未通过相应干预实验确定。不能把这些假设写成已证实原因。','', '建议下一步使用确实完成4层的老师、扩大独立来源对局，并做“上下文输入/标签平均方式”的对照；检查留出标签误差和学生真实成功率，再决定教师更新比例；不宜只对现有951条标签增加训练轮数。','', '复现入口、协议、完整逐局记录和结构化结果位于`training/diagnosis-v7/`。']
Path('RL-V7-DIAGNOSIS.md').write_text('\n'.join(lines)+'\n')
